head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70206";
scwin.disclsAlertMsg = null;
scwin.disclsAlertPageMoveMsg = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.disclsAlertMsg = $c.util.getComponent('disclsAlertMsg');
        scwin.disclsAlertPageMoveMsg = $c.util.getComponent('disclsAlertPageMoveMsg');
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70206.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        $c.util.getComponent("ipt_sPw").focus();
        scwin.alertDisclsPageMove("최초 접근시 화면접근번호를 설정하시기바랍니다.");
        scwin.alertDiscls("화면접근번호가 재설정 되었습니다.");
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).returnDisclsPage === 'function' ? (scwin.openerScwin()).returnDisclsPage() : void 0), $c.win.closePopup([]));
        $c.win.closePopup();
        scwin.alertDiscls("화면접근번호를 확인하십시오.");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70206.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
