///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDisclsConfirmLogin
 * @description fn Discls Confirm Login 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDisclsConfirmLogin = async function () {
    const sbmOptions = {
        id: "tx_fnDisclsConfirmLogin",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=disclsConfirmLogin",
        ref: "dma_fnDisclsConfirmLoginReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnDisclsConfirmAdj
 * @description fn Discls Confirm Adj 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDisclsConfirmAdj = async function () {
    const sbmOptions = {
        id: "tx_fnDisclsConfirmAdj",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=disclsConfirmAdjPop",
        ref: "dma_fnDisclsConfirmAdjReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_closeAlertPageMoveDiscls
 * @description close Alert Page Move Discls 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_closeAlertPageMoveDiscls = async function () {
    const sbmOptions = {
        id: "tx_closeAlertPageMoveDiscls",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=disclsConfirmAdjPop",
        ref: "dma_closeAlertPageMoveDisclsReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name enterDisclsConfirmLogin
 * @description enter Discls Confirm Login 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterDisclsConfirmLogin = async function () {
    if (event.keyCode === 13) {
        await scwin.fnDisclsConfirmLogin();
    }
};

/**
 * @method
 * @name fnDisclsConfirmLogin
 * @description fn Discls Confirm Login 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDisclsConfirmLogin = async function () {
    if ($('#ipt_sPw', $('#disclsConfirm')).val() === "") {
        scwin.alertDiscls("화면접근번호를 입력하십시오.");
        $c.util.getComponent("ipt_sPw").focus();
        return;
    }

    await scwin.tx_fnDisclsConfirmLogin();
};

/**
 * @method
 * @name fnDisclsConfirmAdj
 * @description fn Discls Confirm Adj 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDisclsConfirmAdj = async function () {
    await scwin.tx_fnDisclsConfirmAdj();
};

/**
 * @method
 * @name resizeWindow
 * @description resize Window 처리
 * @param {*} win win
 * @returns {void}
 * @hidden N
 */
scwin.resizeWindow = function (win) {
    win.resizeTo(770, 450);
};

/**
 * @method
 * @name alertDiscls
 * @description alert Discls 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.alertDiscls = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertDisclsText')[0].innerText = msg;
    scwin.disclsAlertMsg.setStyle("display", "");
};

/**
 * @method
 * @name closeAlertDiscls
 * @description close Alert Discls 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeAlertDiscls = function () {
    scwin.disclsAlertMsg.setStyle("display", "none");
};

/**
 * @method
 * @name alertDisclsPageMove
 * @description alert Discls Page Move 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.alertDisclsPageMove = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertDisclsPageMoveText')[0].innerText = msg;
    scwin.disclsAlertPageMoveMsg.setStyle("display", "");
};

/**
 * @method
 * @name closeAlertPageMoveDiscls
 * @description close Alert Page Move Discls 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeAlertPageMoveDiscls = async function () {
    scwin.disclsAlertPageMoveMsg.setStyle("display", "none");

    await scwin.tx_closeAlertPageMoveDiscls();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
